"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

export interface BentoItem {
  id: string;
  title: React.ReactNode;
  description: React.ReactNode;
  icon: React.ReactNode;
  colors: {
    selectedBg: string;
    selectedHover: string;
    descText: string;
  };
}

export interface BentoComponentProps {
  defaultValue?: string;
  value?: string;
  onChange?: (id: string) => void;
  className?: string;
}

/* --- SVG Icons --- */

const LightbulbIcon = () => (
  <svg
    width="22"
    height="22"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.7"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M9 16.2C7.18 15.07 6 13.06 6 10.75C6 7.3 8.69 4.5 12 4.5C15.31 4.5 18 7.3 18 10.75C18 13.06 16.82 15.07 15 16.2H9Z" />
    <line x1="9.5" y1="19" x2="14.5" y2="19" />
    <line x1="11" y1="21.5" x2="13" y2="21.5" />
  </svg>
);

const SchoolCapIcon = () => (
  <svg
    width="22"
    height="22"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.7"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M12 4L3 8.5L12 13L21 8.5L12 4Z" />
    <path d="M6.5 10.5V15.5L12 18.5L17.5 15.5V10.5" />
    <path d="M21 8.5V15.5" />
  </svg>
);

const CodeIcon = () => (
  <svg
    width="22"
    height="22"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.7"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <polyline points="16 18 22 12 16 6" />
    <polyline points="8 6 2 12 8 18" />
  </svg>
);

const CompassIcon = () => (
  <svg
    width="22"
    height="22"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.7"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <circle cx="12" cy="12" r="10" />
    <polygon points="16.24 7.76 14.12 14.12 7.76 16.24 9.88 9.88 16.24 7.76" />
  </svg>
);

const CheckIcon = () => (
  <svg
    width="11"
    height="11"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.4"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <polyline points="20 6 9 17 4 12" />
  </svg>
);

const ROW_ONE_OPTIONS: BentoItem[] = [
  {
    id: "organise",
    title: (
      <>
        Organise your
        <br />
        ideas
      </>
    ),
    description: (
      <>
        Group chats by topic and
        <br />
        ground on your sources.
      </>
    ),
    icon: <LightbulbIcon />,
    colors: {
      selectedBg: "#182052",
      selectedHover: "#1b245c",
      descText: "#949ec2",
    },
  },
  {
    id: "study",
    title: "Study and learn",
    description: (
      <>
        Get custom lessons and
        <br />
        track your progress.
      </>
    ),
    icon: <SchoolCapIcon />,
    colors: {
      selectedBg: "#142a38",
      selectedHover: "#183243",
      descText: "#89b0c7",
    },
  },
];

const ROW_TWO_OPTIONS: BentoItem[] = [
  {
    id: "build",
    title: (
      <>
        Build & develop
        <br />
        components
      </>
    ),
    description: (
      <>
        Fast prototyping with AI
        <br />
        and production patterns.
      </>
    ),
    icon: <CodeIcon />,
    colors: {
      selectedBg: "#2d163d",
      selectedHover: "#361b4a",
      descText: "#c49ac7",
    },
  },
  {
    id: "explore",
    title: "Explore insights",
    description: (
      <>
        Analyze trends and discover
        <br />
        high-impact workflows.
      </>
    ),
    icon: <CompassIcon />,
    colors: {
      selectedBg: "#1b2c24",
      selectedHover: "#21362c",
      descText: "#97bea8",
    },
  },
];

// Physical Spring Transition
const SPRING_TRANSITION = {
  type: "spring",
  stiffness: 350,
  damping: 32,
  mass: 1,
} as const;

export const Component: React.FC<BentoComponentProps> = ({
  defaultValue = "study",
  value,
  onChange,
  className = "",
}) => {
  const [internalSelectedId, setInternalSelectedId] =
    useState<string>(defaultValue);

  const activeId = value !== undefined ? value : internalSelectedId;

  const handleSelect = (id: string) => {
    if (value === undefined) {
      setInternalSelectedId(id);
    }
    onChange?.(id);
  };

  const isRowOneActive = ROW_ONE_OPTIONS.some((item) => item.id === activeId);
  const isRowTwoActive = ROW_TWO_OPTIONS.some((item) => item.id === activeId);

  const renderCard = (item: BentoItem, isRowActive: boolean) => {
    const isSelected = activeId === item.id;
    const cardWidth = isRowActive ? (isSelected ? 224 : 182) : 203;

    return (
      <motion.button
        key={item.id}
        role="radio"
        aria-checked={isSelected}
        type="button"
        onClick={() => handleSelect(item.id)}
        initial={false}
        animate={{
          width: cardWidth,
          backgroundColor: isSelected ? item.colors.selectedBg : "#141416",
        }}
        whileHover={{
          backgroundColor: isSelected ? item.colors.selectedHover : "#1b1b1e",
        }}
        whileTap={{
          scale: 0.985,
        }}
        transition={{
          width: SPRING_TRANSITION,
          backgroundColor: { duration: 0.18, ease: "easeOut" },
          scale: { duration: 0.1 },
        }}
        className="relative flex h-[148px] cursor-pointer flex-col items-start justify-start overflow-hidden rounded-[16px] border-0 p-[18px] text-left outline-none focus-visible:ring-1 focus-visible:ring-white/20 select-none"
      >
        {/* Animated Check Badge */}
        <AnimatePresence initial={false}>
          {isSelected && (
            <motion.div
              key="check"
              initial={{ opacity: 0, scale: 0.4 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.5 }}
              transition={{
                type: "spring",
                stiffness: 450,
                damping: 25,
              }}
              className="absolute top-[16px] right-[16px] flex h-[22px] w-[22px] items-center justify-center rounded-full bg-[#111217] text-[#dcdde6]"
            >
              <CheckIcon />
            </motion.div>
          )}
        </AnimatePresence>

        {/* Icon with Subtle Reactive Lift */}
        <motion.div
          animate={{
            scale: isSelected ? 1.05 : 1,
            color: isSelected ? "#ffffff" : "#e2e3e8",
          }}
          transition={{ duration: 0.2 }}
        >
          {item.icon}
        </motion.div>

        {/* Title Container */}
        <div className="mt-[10px] w-[188px] text-[16.5px] leading-[1.26] font-normal tracking-[-0.01em] text-[#e4e5ea]">
          {item.title}
        </div>

        {/* Coordinated Description Reveal */}
        <AnimatePresence initial={false}>
          {isSelected && (
            <motion.div
              key="desc"
              initial={{ opacity: 0, y: 5 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 3 }}
              transition={{
                opacity: { duration: 0.16, delay: 0.04, ease: "easeOut" },
                y: { type: "spring", stiffness: 380, damping: 28 },
              }}
              style={{ color: item.colors.descText }}
              className="mt-[6px] w-[188px] text-[13.2px] leading-[1.34] font-normal tracking-[-0.005em]"
            >
              {item.description}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.button>
    );
  };

  return (
    <div
      role="radiogroup"
      aria-label="Select an option"
      className={`flex w-full items-center justify-center bg-[#0b0b0c] p-6 antialiased select-none font-sans ${className}`}
    >
      <div className="flex flex-col gap-[12px]">
        {/* Top Row */}
        <div className="flex items-center gap-[12px]">
          {ROW_ONE_OPTIONS.map((item) => renderCard(item, isRowOneActive))}
        </div>

        {/* Bottom Row */}
        <div className="flex items-center gap-[12px]">
          {ROW_TWO_OPTIONS.map((item) => renderCard(item, isRowTwoActive))}
        </div>
      </div>
    </div>
  );
};

export default Component;

