    <path d="M6.5 10.5V15.5L12 18.5L17.5 15.5V10.5" />
    <path d="M21 8.5V15.5" />
  </svg>
);

const CheckIcon = () => (
  <svg
    width="12"
    height="12"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.5"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <polyline points="20 6 9 17 4 12" />
  </svg>
);

const DEFAULT_OPTIONS: InteractiveCardOption[] = [
  {
    id: "organise",
    title: (
      <>
        Organise your
        <br />
        ideas
      </>
    ),
    description: "Group chats by topic and ground on your sources.",
    icon: <LightbulbIcon />,
  },
  {
    id: "study",
    title: (
      <>
        Study and
        <br />
        learn
      </>
    ),
    description: "Get custom lessons and track your progress.",
    icon: <SchoolCapIcon />,
  },
];

export const InteractiveCardSelector: React.FC<
  InteractiveCardSelectorProps
> = ({
  options = DEFAULT_OPTIONS,
  defaultValue = "study",
  value,
  onChange,
  className,
}) => {
  const [internalSelectedId, setInternalSelectedId] =
    useState<string>(defaultValue);

  const activeId = value !== undefined ? value : internalSelectedId;

  const handleSelect = (id: string) => {
    if (value === undefined) {
      setInternalSelectedId(id);
    }
    onChange?.(id);
  };

  return (
    <div
      role="radiogroup"
      aria-label="Selection options"
      className={cn(
        "flex w-full items-center justify-center bg-[#0b0b0c] p-6 antialiased select-none font-sans",
        className
