"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

interface OptionItem {
  id: string;
  title: React.ReactNode;
  description: React.ReactNode;
  icon: React.ReactNode;
}

const LightbulbIcon = () => (
  <svg
    width="22"
    height="22"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.7"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M9 16.2C7.18 15.07 6 13.06 6 10.75C6 7.3 8.69 4.5 12 4.5C15.31 4.5 18 7.3 18 10.75C18 13.06 16.82 15.07 15 16.2H9Z" />
    <line x1="9.5" y1="19" x2="14.5" y2="19" />
    <line x1="11" y1="21.5" x2="13" y2="21.5" />
  </svg>
);

const SchoolCapIcon = () => (
  <svg
    width="22"
    height="22"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.7"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M12 4L3 8.5L12 13L21 8.5L12 4Z" />
    <path d="M6.5 10.5V15.5L12 18.5L17.5 15.5V10.5" />
    <path d="M21 8.5V15.5" />
  </svg>
);

const CheckIcon = () => (
  <svg
    width="11"
    height="11"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.4"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <polyline points="20 6 9 17 4 12" />
  </svg>
);

const OPTIONS: OptionItem[] = [
  {
    id: "organise",
    title: (
      <>
        Organise your
        <br />
        ideas
      </>
    ),
    description: (
      <>
        Group chats by topic and
        <br />
        ground on your sources.
      </>
    ),
    icon: <LightbulbIcon />,
  },
  {
    id: "study",
    title: "Study and learn",
    description: (
      <>
        Get custom lessons and
        <br />
        track your progress.
      </>
    ),
    icon: <SchoolCapIcon />,
  },
];

// Material 3 / Google UI emphasized glide curve (zero overshoot bounce)
const GLIDE_TRANSITION = {
  duration: 0.32,
  ease: [0.2, 0.0, 0.0, 1.0] as const,
};

export const ExactProjectSelector: React.FC = () => {
  const [selectedId, setSelectedId] = useState<string>("study");

  return (
    <>
      {/* Load Plus Jakarta Sans to match the single-story 'g' and clean geometric numerals/letters */}
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500&display=swap');
        .gemini-card-font {
          font-family: 'Google Sans', 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
        }
      `}</style>

      <div className="gemini-card-font flex min-h-screen w-full items-center justify-center bg-[#0b0b0c] p-6 antialiased select-none">
        <div className="flex items-center gap-[12px]">
          {OPTIONS.map((item) => {
            const isSelected = selectedId === item.id;

            return (
              <motion.button
                key={item.id}
                type="button"
                onClick={() => setSelectedId(item.id)}
                initial={false}
                animate={{
                  width: isSelected ? 224 : 182,
                  backgroundColor: isSelected ? "#182052" : "#141416",
                }}
                whileHover={{
                  backgroundColor: isSelected ? "#1b245c" : "#1b1b1e",
                }}
                transition={{
                  width: GLIDE_TRANSITION,
                  backgroundColor: { duration: 0.18, ease: "easeOut" },
                }}
                className="relative flex h-[148px] cursor-pointer flex-col items-start justify-start overflow-hidden rounded-[16px] border-0 p-[18px] text-left outline-none"
              >
                {/* Checkmark Badge pinned to top-right */}
                <AnimatePresence initial={false}>
                  {isSelected && (
                    <motion.div
                      key="check"
                      initial={{ opacity: 0, scale: 0.6 }}
                      animate={{ opacity: 1, scale: 1 }}
                      exit={{ opacity: 0, scale: 0.6 }}
                      transition={{ duration: 0.16, ease: [0.2, 0, 0, 1] }}
                      className="absolute top-[16px] right-[16px] flex h-[22px] w-[22px] items-center justify-center rounded-full bg-[#111217] text-[#dcdde6]"
                    >
                      <CheckIcon />
                    </motion.div>
                  )}
                </AnimatePresence>

                {/* Icon (Locked top-left position) */}
                <div className="text-[#e2e3e8]">{item.icon}</div>

                {/* Title (Fixed width container prevents text reflow jitter during width animation) */}
                <div className="mt-[10px] w-[188px] text-[16.5px] leading-[1.26] font-normal tracking-[-0.01em] text-[#e4e5ea]">
                  {item.title}
                </div>

                {/* Description (Smoothly revealed without shifting title) */}
                <AnimatePresence initial={false}>
                  {isSelected && (
                    <motion.div
                      key="desc"
                      initial={{ opacity: 0, y: 3 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, y: 2 }}
                      transition={{
                        opacity: { duration: 0.18, delay: 0.03, ease: "easeOut" },
                        y: { duration: 0.22, ease: [0.2, 0, 0, 1] },
                      }}
                      className="mt-[6px] w-[188px] text-[13.2px] leading-[1.34] font-normal tracking-[-0.005em] text-[#949ec2]"
                    >
                      {item.description}
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.button>
            );
          })}
        </div>
      </div>
    </>
  );
};

export default ExactProjectSelector;

